//! # SPSC Ring Buffer Queue Implementation
//!
//! This module implements a thread-safe, non-blocking Single-Producer Single-Consumer (SPSC)
//! queue using a ring buffer strategy backed by `AtomicUsize`.
//!
//! ## Architectural Decisions
//!
//! 1. **State Packing (False Sharing Mitigation):**
//!    We store the `Head` and `Tail` indices of the ring buffer inside a **single** `AtomicUsize`.
//!    Packing them as `(Head << 32) | Tail` ensures they occupy exactly one memory word (cache line slot).
//!    If `Head` and `Tail` were separate `AtomicUsize` instances, they might reside on adjacent
//!    cache lines. Concurrent writes could trigger "False Sharing", where the CPU invalidates
//!    the entire cache line for both variables due to a write to one, causing unnecessary
//!    memory traffic and coherence overhead. By packing into one `AtomicUsize`, we enforce
//!    cache-line alignment padding implicitly.
//!
//! 2. **Memory Ordering Barriers (`Acquire`, `Release`, `Relaxed`):**
//!    In `std::sync::atomic`, the `Ordering` enum instructs the compiler/CPU about instruction
//!    reordering constraints around the atomic operation.
//!    *   `Ordering::Acquire`: Prevents the compiler from moving memory operations *before* the
//!        atomic instruction. This is critical for the **Producer** to ensure the "Check"
//!        (reading the current state) happens strictly before the "Commit".
//!    *   `Ordering::Release`: Prevents the compiler from moving memory operations *after* the
//!        atomic instruction. This is critical for the **Consumer** to ensure the "Update"
//!        is visible before any subsequent logic.
//!    *   `Ordering::Relaxed`: Allows reordering. Generally unsafe for lock-free queues.
//!
//! 3. **Non-Blocking (Lock-Free) Design:**
//!    We use Optimistic CAS (Compare-And-Swap). If the CAS fails (expected value mismatch),
//!    we retry immediately. We do not block on a mutex lock. This is "Lock-Free" concurrency.
//!    The loop ensures we eventually succeed or the state changes externally.

use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Arc;

/// Configuration for the ring buffer capacity.
/// Fixed size to simplify index arithmetic.
const CAPACITY: usize = 1024;

/// Encodes the queue state (Head, Tail) into a single `usize`.
/// We assume `usize` is 64-bit (x86_64, aarch64).
/// State = `(Head << 32) | Tail`.
/// If `usize` is 32-bit, this will overflow; this implementation targets 64-bit systems.
#[inline]
fn pack_state(head: usize, tail: usize) -> usize {
    // Ensure head and tail fit in 32 bits each.
    ((head & 0xFFFFFFFF) << 32) | (tail & 0xFFFFFFFF)
}

#[inline]
fn unpack_state(state: usize) -> (usize, usize) {
    let head = state >> 32;
    let tail = state & 0xFFFFFFFF;
    (head, tail)
}

pub struct SpScQueue {
    /// Shared atomic state.
    state: Arc<AtomicUsize>,
}

impl SpScQueue {
    /// Creates a new SPSC Queue.
    /// Initializes the state to (0, 0) (Empty).
    pub fn new() -> Self {
        let state = Arc::new(AtomicUsize::new(0));
        Self { state }
    }

    /// Pushes an item (Producer).
    /// Updates the `Tail` index.
    /// Uses `Ordering::Acquire` to ensure the read-check happens before the write-commit
    /// in the compiler's instruction stream.
    pub fn push(&self) -> Result<(), String> {
        // 1. Read current state.
        let current = self.state.load(Ordering::Relaxed);
        let (mut head, mut tail) = unpack_state(current);

        // 2. Check if buffer is full.
        // In a ring buffer, full means (Tail + 1) % Capacity == Head.
        // Empty means Head == Tail.
        if head == tail {
            // Buffer is empty. Start at 0.
            head = 0;
            tail = 0;
        } else {
            // Advance Tail.
            tail = (tail + 1) % CAPACITY;
        }

        let new_state = pack_state(head, tail);

        // 3. Optimistic CAS (Compare-And-Swap).
        // We use `Ordering::Acquire` here.
        // Rationale: We want to ensure that the *verification* of the `current` value
        // is not reordered *after* the atomic update by the compiler.
        // This guarantees that if the CAS succeeds, the `current` value we read was
        // actually the value present at the moment of the swap.
        match self.state.compare_and_swap(current, new_state, Ordering::Acquire) {
            Ok(_) => {
                // Success. The state was `current`, now it is `new_state`.
                Ok(())
            }
            Err(expected) => {
                // CAS Failed. The state changed while we were preparing the update.
                // This is the "Non-Blocking" part: we do not block. We retry.
                // In a real high-performance system, we would loop here until success.
                // For this demo, we return an error to indicate contention.
                Err(format!("CAS failed, expected state was {}", expected))
            }
        }
    }

    /// Pops an item (Consumer).
    /// Updates the `Head` index.
    /// Uses `Ordering::Release` to ensure the update is committed before any
    /// subsequent memory operations are reordered after it.
    pub fn pop(&self) -> Result<usize, String> {
        // 1. Read current state.
        let current = self.state.load(Ordering::Relaxed);
        let (mut head, mut tail) = unpack_state(current);

        // 2. Check if buffer is empty.
        if head == tail {
            // Empty. Return error or special value.
            return Err("Buffer Empty".to_string());
        }

        // 3. Advance Head.
        let new_head = (head + 1) % CAPACITY;
        let new_state = pack_state(new_head, tail);

        // 4. Optimistic CAS.
        // We use `Ordering::Release`.
        // Rationale: We want to ensure that the *commit* of the `new_state`
        // is not reordered *before* any subsequent memory operations.
        // This ensures that once the CAS returns Ok, the new state is visible
        // to any following code in the same thread context (compiler view).
        match self.state.compare_and_swap(current, new_state, Ordering::Release) {
            Ok(_) => {
                // Success.
                Ok(head) // Return the index that was popped (old head).
            }
            Err(expected) => {
                Err(format!("CAS failed, expected state was {}", expected))
            }
        }
    }

    /// Helper to get current state (for debugging/testing).
    pub fn get_state(&self) -> (usize, usize) {
        let current = self.state.load(Ordering::Relaxed);
        unpack_state(current)
    }
}

impl Default for SpScQueue {
    fn default() -> Self {
        Self::new()
    }
}

